package com.aliothmoon.maafw.once;
import org.junit.Test;import static org.junit.Assert.*;import java.nio.file.*;
public class OwnStateSummaryTest {
 @Test public void wrongUidCannotRead(){String s=OwnStateSummary.inspect("SECRET_ROOT",12345,12346,()->0,()->false);assertTrue(s.contains("ROOT_UNAVAILABLE"));assertFalse(s.contains("SECRET_ROOT"));assertTrue(s.contains("actionAuthority=false"));}
 @Test public void absentRootNeverCreated()throws Exception{Path parent=Files.createTempDirectory("own-summary");Path missing=parent.resolve("missing");String s=OwnStateSummary.inspectRoot(missing,()->100,()->false);assertFalse(Files.exists(missing));assertTrue(s.contains("ABSENT_LOCAL")||s.contains("absentLocal="));assertTrue(s.contains("historyComplete=false"));assertTrue(s.contains("HOLD"));Files.delete(parent);}
 @Test public void cancellationNeverReturnsInventory()throws Exception{Path root=Files.createTempDirectory("own-summary");String s=OwnStateSummary.inspectRoot(root,()->100,()->true);assertTrue(s.contains("CANCELLED_OR_EXPIRED"));assertFalse(s.contains("inventoryEntries="));Files.delete(root);}
 @Test public void sourceNeverInvokesMutationOrRawOutput()throws Exception{String rel="app/src/main/java/com/aliothmoon/maafw/once/OwnStateSummary.java";Path p=Path.of(System.getProperty("staging.root","."),rel);if(!Files.exists(p))p=Path.of("..",rel);String s=Files.readString(p);for(String x:new String[]{"new AttemptJournal","new Atomic","getFilesDir(","getNoBackupFilesDir(","Files.write","createDirectories","getSharedPreferences","newProcess","performAction","readFully"})assertFalse(x,s.contains(x));assertTrue(s.contains("sessionReceipts=NOT_PERSISTED"));assertTrue(s.contains("writerLease=NOT_ACQUIRED"));assertTrue(s.contains("contentValidation=NOT_INSPECTED owner=UNKNOWN"));}
 @Test public void activityRoutesBeforeBingAndKeepsScope()throws Exception{String rel="app/src/main/java/com/aliothmoon/maafw/once/DormantCaptureConfirmationActivity.java";Path p=Path.of(System.getProperty("staging.root","."),rel);if(!Files.exists(p))p=Path.of("..",rel);String s=Files.readString(p);int create=s.indexOf("@Override protected void onCreate");int local=s.indexOf("if(OwnStateSummaryUi.ACTIVE)",create);assertTrue(local>s.indexOf("super.onCreate(state)",create));assertTrue(local<s.indexOf("installed=BingPackageMetadata.read",create));assertTrue(s.contains("getApplicationInfo().dataDir"));assertTrue(s.contains("if(ownStateCancelled||android.os.SystemClock.elapsedRealtime()>=ownStateEnd||!isResumedForApproval())summaryRejected();"));assertTrue(s.contains("onPause(){ownStateCancelled=true;"));}
 @Test public void summaryChargesFailedReadsAndCountsBeforeOutputCap()throws Exception{
  String rel="app/src/main/java/com/aliothmoon/maafw/once/OwnStateSummary.java";Path p=Path.of(System.getProperty("staging.root","."),rel);if(!Files.exists(p))p=Path.of("..",rel);String s=Files.readString(p);
  assertTrue(s.indexOf("bytes+=read.reservedBytes()")<s.indexOf("if(read.status()==OwnStateReadOnlyFiles.Status.ABSENT_LOCAL)"));
  assertTrue(s.contains("MAX_TOTAL_BYTES-bytes,end,clock"));assertFalse(s.contains("bytes+=data.length"));
  for(String token:new String[]{"schemaMalformed++","schemaUnsupported++","pending++"})assertTrue(token,s.indexOf(token)>=0&&s.indexOf(token)<s.indexOf("if(details.size()<MAX_OUTPUT)"));
  assertTrue(s.contains(" bytesReserved="));assertFalse(s.contains(" bytesRead="));
 }
}
